INSERT INTO repo_kcrs (kcr_id, name, domain, concept_category, concept_type, definition, scope, core_principles, semantic_description, keywords_synonyms, status) VALUES ('KCR_000701', 'reflux', 'Engineering & Technology', 'Mass Transfer Operations', 'Technical Concept', 'Liquid returned to a distillation column from condensed overhead vapour to improve separation.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of reflux within Mass Transfer Operations, particularly where the Distillation module establishes its technical context.', 'Core considerations include the defining characteristics of reflux, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'Liquid returned to a distillation column from condensed overhead vapour to improve separation. Within Distillation, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of reflux within Mass Transfer Operations, particularly where the Distillation module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of reflux, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'reflux; Core considerations include the defining characteristics of reflux, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Mass Transfer Operations', 'Active'), ('KCR_000702', 'tray efficiency', 'Engineering & Technology', 'Mass Transfer Operations', 'Technical Concept', 'A measure of how closely an actual tray approaches the mass-transfer performance of an ideal equilibrium stage.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of tray efficiency within Mass Transfer Operations, particularly where the Distillation module establishes its te